<script setup lang="ts">
import { computed, onMounted, onUnmounted, shallowRef, useTemplateRef, watch } from 'vue';
import { ElMessage } from '@/utils/message';
import { cameraAt, cloneDirector, directorKinds, emptyDirector, newDirectorObject, objectAt, resizeDirector, sampleDirector, performanceDirector, totalFrames, upsertKey, validateDirector, type CameraKey, type DirectorDocument, type DirectorKind, type DirectorObject, type ObjectKey, type Vec3 } from '@/utils/dramaDirector';
import { useDirectorDocument } from './useDirectorDocument';
import DirectorViewport from './DirectorViewport.vue';
import DirectorInspector from './DirectorInspector.vue';
import DirectorTimeline from './DirectorTimeline.vue';
import DirectorGuide from './DirectorGuide.vue';
import DirectorImportDialog from './DirectorImportDialog.vue';
import DirectorCaptureDialog from './DirectorCaptureDialog.vue';
import { useDirectorPerformance } from './useDirectorPerformance';
import { battleDirector } from '@/utils/dramaDirectorBattle';
import { uploadVideoReference, type VideoReference } from '@/api/shortDrama/videoReferences';
const props = defineProps<{ projectId: string; documentId: string; title: string; fork?: string }>();
const emit = defineEmits<{ close: []; saved: [summary: { seconds: number; content: string; directorSourceId?: string }] }>();
const store = useDirectorDocument(props.projectId, props.documentId, props.fork), doc = store.document;
const selected = shallowRef(''), frame = shallowRef(0), playing = shallowRef(false), tool = shallowRef<'translate' | 'rotate' | 'scale' | 'pose'>('translate'), guides = shallowRef(true);
const viewport = useTemplateRef<InstanceType<typeof DirectorViewport>>('viewport'), exporting = shallowRef(false), progress = shallowRef(0), message = shallowRef('');
const exportKind = shallowRef<'video' | 'frame'>('video');
const guideOpen = shallowRef(false);
const importOpen = shallowRef(false);
const captureOpen = shallowRef(false);
const menu = shallowRef<{ x: number; y: number }>(), videoUrl = shallowRef('');
const exportedVideo=shallowRef<Blob>(),videoReference=shallowRef<VideoReference>(),referenceBusy=shallowRef(false),referenceUnknown=shallowRef(false);
let playback = 0, controller: AbortController | undefined;
const menuPosition = computed(() => menu.value ? {left:`${Math.max(8,Math.min(menu.value.x,window.innerWidth-210))}px`,top:`${Math.max(8,Math.min(menu.value.y,window.innerHeight-285))}px`} : {});
function closeVideo() { if(referenceBusy.value)return;URL.revokeObjectURL(videoUrl.value); videoUrl.value='';exportedVideo.value=undefined; }
async function saveVideoReference() {
  if(!exportedVideo.value||referenceBusy.value||videoReference.value||referenceUnknown.value)return;
  referenceBusy.value=true;
  try {videoReference.value=await uploadVideoReference(props.projectId,new File([exportedVideo.value],`${filename()}-白模预演.mp4`,{type:'video/mp4'}));ElMessage.success('动作参考已保存，在分镜中刷新参考列表并选用');}
  catch(error){referenceUnknown.value=true;message.value=(error instanceof Error?error.message:'动作参考保存未确认')+'；请先在分镜参考列表核对，避免重复上传';}
  finally{referenceBusy.value=false;}
}
const performanceEditor = useDirectorPerformance(doc,selected,frame,mutate,seek,patchKey);
const end = computed(() => totalFrames(doc.value) - 1);
const object = computed(() => doc.value.objects.find(o => o.id === selected.value));
function stop() { playing.value = false; cancelAnimationFrame(playback); }
function seek(value: number) { stop(); frame.value = Math.max(0, Math.min(end.value, Math.round(Number.isFinite(value) ? value : 0))); }
function select(id: string) { stop(); if(tool.value==='pose' && doc.value.objects.find(o=>o.id===id)?.kind!=='actor')tool.value='translate'; selected.value = id; menu.value = undefined; }
function mutate(action: (document: DirectorDocument) => void) {
  if (!store.ready.value || exporting.value) return false; stop(); message.value = '';
  try { const next = cloneDirector(doc.value); action(next); store.replace(next); return true; } catch (e) { message.value = e instanceof Error ? e.message : '编辑未完成'; return false; }
}
function add(kind: DirectorKind) { let id = ''; mutate(next => { const o = newDirectorObject(kind, next.objects.filter(o => o.kind === kind).length); next.objects.push(o); id = o.id; }); if (id && doc.value.objects.some(o => o.id === id)) { selected.value = id; frame.value = 0; } menu.value = undefined; }
function patchObject(id: string, patch: Partial<DirectorObject>) { mutate(next => { const o = next.objects.find(o => o.id === id); if (o && !(o.locked && Object.keys(patch).some(key=>!['locked','visible','name','color'].includes(key)))) Object.assign(o, patch); }); }
function patchKey(patch: Partial<ObjectKey>) { mutate(next => { const o = next.objects.find(o => o.id === selected.value); if (!o || o.locked) return; o.keys = upsertKey(o.keys, { ...objectAt(o, frame.value), ...patch, frame: frame.value }); }); }
function patchCamera(patch: Partial<CameraKey>) { mutate(next => { next.camera.keys = upsertKey(next.camera.keys, { ...cameraAt(next, frame.value), ...patch, frame: frame.value }); }); }
function key() { if (selected.value === 'camera') patchCamera({}); else patchKey({}); }
function deleteKey() { if (!frame.value) return; mutate(next => { if (selected.value === 'camera') next.camera.keys = next.camera.keys.filter(k => k.frame !== frame.value); else { const o = next.objects.find(o => o.id === selected.value); if (o && !o.locked) o.keys = o.keys.filter(k => k.frame !== frame.value); } }); }
function remove() { if (object.value?.locked) return; mutate(next => { const id=selected.value; next.objects = next.objects.filter(o => o.id !== id); next.objects.forEach(o=>{if(o.lookAtId===id)delete o.lookAtId;if(o.targetId===id)delete o.targetId;}); if(next.camera.follow?.objectId===id)delete next.camera.follow; }); if (!object.value) selected.value = ''; menu.value = undefined; }
function duplicate() { let id = ''; mutate(next => { const o = next.objects.find(o => o.id === selected.value); if (!o) return; const clone = cloneDirector(o); clone.id = crypto.randomUUID(); clone.name = `${o.name.slice(0, 90)} · 副本`; clone.locked = false; clone.keys.forEach(k => { k.position[0] += 1; }); next.objects.push(clone); id = clone.id; }); if (id && doc.value.objects.some(o => o.id === id)) selected.value = id; menu.value = undefined; }
function transform(id: string, position: Vec3, yaw: number, scale: Vec3) {
  if (id === 'view') { selected.value = 'camera'; patchCamera({ position, target: scale }); return; }
  selected.value = id;
  if (id === 'camera') patchCamera({ position });
  else mutate(next => { const o = next.objects.find(o => o.id === id); if (!o || o.locked) return;
    o.keys = upsertKey(o.keys, { ...objectAt(o, frame.value), frame: frame.value, position: position.map(n => Math.max(-100, Math.min(100, n))) as Vec3, yaw });
    o.scale = scale.map(n => Math.max(.1, Math.min(20, n))) as Vec3;
  });
}
function play() {
  if (exporting.value) return; if (playing.value) { stop(); return; } if (frame.value >= end.value) frame.value = 0;
  playing.value = true; const startFrame = frame.value, startTime = performance.now();
  function tick(now: number) { frame.value = Math.min(end.value, startFrame + Math.floor((now - startTime) / 1000 * doc.value.fps)); if (frame.value >= end.value) { stop(); return; } playback = requestAnimationFrame(tick); }
  playback = requestAnimationFrame(tick);
}
function history(name: 'undo' | 'redo') { if (exporting.value) return; stop(); store[name](); frame.value = Math.min(frame.value, end.value); if (selected.value !== 'camera' && !doc.value.objects.some(o => o.id === selected.value)) selected.value = ''; }
async function save() { if (await store.save()) { emit('saved', { directorSourceId: undefined, seconds: doc.value.duration, content: `${doc.value.objects.length} 个场景对象 · ${doc.value.camera.keys.length} 个机位关键帧 · ${doc.value.aspect} / 24 fps` }); return true; } return false; }
async function close() { if (exporting.value) { message.value = '视频正在导出，可先取消导出再返回画布'; return; } stop(); if (!store.ready.value && !store.dirty.value || await save()) emit('close'); }
function download(blob: Blob, name: string) { const url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 30_000); }
const filename = () => props.title.replace(/[\\/:*?"<>|]/g, '-').slice(0, 80);
function backup() { download(new Blob([JSON.stringify(doc.value, null, 2)], { type: 'application/json' }), `${filename()}-导演工程.json`); }
async function reload() { if (store.dirty.value) backup(); stop(); await store.load(); selected.value = ''; frame.value = 0; }
function importDocument(imported: DirectorDocument) { if (exporting.value || !store.ready.value) return; if (store.dirty.value) backup(); stop(); store.replace(imported); frame.value = 0; selected.value = ''; importOpen.value = false; captureOpen.value = false; }
async function importFile(event: Event) { const input = event.target as HTMLInputElement; try { const file = input.files?.[0]; if (!file) return; if (file.size > 1024 * 1024) throw new Error('工程文件不能超过 1MB'); importDocument(validateDirector(JSON.parse(await file.text()))); } catch (e) { message.value = e instanceof Error ? e.message : '导入失败'; } finally { input.value = ''; } }
function duration(event: Event) { const value = Number((event.target as HTMLInputElement).value); if (!Number.isInteger(value) || value < 2 || value > 60) { message.value = '片段长度为 2–60 秒的整数'; return; } stop(); store.replace(resizeDirector(doc.value, value)); frame.value = Math.min(frame.value, end.value); }
function preset(performance = false) { stop(); store.replace(performance ? performanceDirector() : sampleDirector()); frame.value = 0; selected.value = doc.value.objects[0]!.id; }
function battlePreset() { stop(); store.replace(battleDirector()); frame.value=0; selected.value=doc.value.objects.find(o=>o.kind==='cannon')!.id; }
function clear() { stop(); store.replace(emptyDirector()); selected.value = ''; frame.value = 0; }
async function exportMedia(kind: 'video' | 'frame') {
  if (exporting.value || !store.ready.value) return; stop(); message.value = ''; exportKind.value = kind; exporting.value = true; progress.value = 0; controller = new AbortController();
  try { const exporter = await import('./directorExport');
    const blob = kind === 'video' ? await exporter.exportDirectorVideo(doc.value, value => { progress.value = value; }, controller.signal) : await exporter.exportDirectorFrame(doc.value, frame.value);
    if (kind === 'video') { if (videoUrl.value) URL.revokeObjectURL(videoUrl.value); videoUrl.value = URL.createObjectURL(blob);exportedVideo.value=blob;videoReference.value=undefined;referenceUnknown.value=false; }
    download(blob, `${filename()}-${kind === 'video' ? '白模预演.mp4' : `第${frame.value}帧.png`}`); ElMessage.success(kind === 'video' ? '24 fps 白模视频已导出，可在窗口中回放' : '摄影机当前画面已导出');
  } catch (e) { message.value = e instanceof Error ? e.message : '导出失败，请确认浏览器支持 H.264 WebCodecs'; } finally { exporting.value = false; controller = undefined; }
}
function keyboard(event: KeyboardEvent) {
  if ((event.target as HTMLElement).closest('input,textarea,select,button,[contenteditable=true]') || exporting.value) return;
  const ctrl = event.ctrlKey || event.metaKey;
  if (ctrl && event.key.toLowerCase() === 's') { event.preventDefault(); void save(); }
  else if (ctrl && event.key.toLowerCase() === 'z') { event.preventDefault(); history(event.shiftKey ? 'redo' : 'undo'); }
  else if (ctrl && event.key.toLowerCase() === 'd') { event.preventDefault(); duplicate(); }
  else if (event.code === 'Space') { event.preventDefault(); play(); }
  else if (event.key === 'Delete') { event.preventDefault(); remove(); }
  else if (event.key === 'Escape') menu.value = undefined;
}
watch(doc, () => { if (videoUrl.value) { URL.revokeObjectURL(videoUrl.value); videoUrl.value = ''; } });
onMounted(() => { document.addEventListener('keydown', keyboard); void store.load(); });
onUnmounted(() => { stop(); controller?.abort(); document.removeEventListener('keydown', keyboard); if (videoUrl.value) URL.revokeObjectURL(videoUrl.value); });
</script>
<template>
  <div class="director-studio" role="dialog" aria-modal="true" aria-label="3D 导演工作台" @pointerdown="menu=undefined">
    <header class="director-header"><div class="director-heading"><button aria-label="返回流程画布" @click="close">←</button><div><small>RUOYI DRAMA / 3D DIRECTOR</small><h1>{{title}} <span>预览版</span></h1></div></div><div class="save-actions"><button @click="guideOpen=true">操作参考 ?</button><span :class="{error:store.error.value}">{{store.error.value ? '工程未保存' : store.saving.value ? '保存中…' : store.dirty.value ? '有未保存修改' : '工程已同步'}}</span><button :disabled="!store.ready.value || exporting" @click="backup">导出工程</button><label :class="{disabled:exporting || !store.ready.value}">导入工程<input type="file" accept="application/json,.json" aria-label="导入导演工程" :disabled="exporting || !store.ready.value" @change="importFile"></label><button :disabled="!store.ready.value || exporting" @click="captureOpen=true">参考视频动作</button><button :disabled="!store.ready.value || exporting" @click="importOpen=true">粘贴工程</button><button :disabled="!store.ready.value || exporting" @click="save">保存工程</button><button class="primary" :disabled="!store.ready.value || exporting" @click="exportMedia('video')">导出白模视频 ↗</button></div></header>
    <div class="director-subbar"><div><span class="preview-note">预演功能尚未正式发布</span><span>摆位、动作、运镜先在白模中排练</span></div><div><label>片段 <input type="number" min="2" max="60" :value="doc.duration" aria-label="预演片段秒数" :disabled="!store.ready.value || exporting" @change="duration"> 秒</label><select :value="doc.aspect" aria-label="预演画幅" :disabled="!store.ready.value || exporting" @change="mutate(next=>{next.aspect=($event.target as HTMLSelectElement).value as DirectorDocument['aspect']})"><option value="16:9">16:9 横屏</option><option value="9:16">9:16 竖屏</option></select><button :disabled="!store.ready.value || exporting" @click="exportMedia('frame')">导出当前帧</button></div></div>
    <div v-if="store.error.value || message" class="director-alert" role="alert"><span>{{store.error.value || message}}</span><template v-if="store.error.value"><button @click="store.ready.value ? save() : store.load()">重试</button><button v-if="store.ready.value" @click="reload">备份并重新加载</button></template><button v-else @click="message=''">×</button></div>
    <div v-if="exporting" class="export-progress" role="status"><span>{{exportKind==='video' ? `正在逐帧导出 ${Math.round(progress*100)}% · ${doc.duration} 秒 / 24 fps` : '正在导出摄影机当前画面…'}}</span><progress v-if="exportKind==='video'" :value="progress" max="1"/><button v-if="exportKind==='video'" @click="controller?.abort()">取消导出</button></div>
    <div v-if="store.ready.value" class="director-body" :class="{busy:exporting}">
      <aside class="scene-sidebar" aria-label="导演场景列表"><div class="scene-heading"><span>场景</span><small>{{doc.objects.length}} 个对象</small></div><div class="add-assets"><button v-for="(label,kind) in directorKinds" :key="kind" :disabled="doc.objects.length>=80" @click="add(kind)"><span>{{kind==='actor' ? '♙' : kind==='door' ? '⊓' : '□'}}</span>＋ {{label}}</button></div><div class="scene-list"><button class="camera-row" :class="{active:selected==='camera'}" @click="select('camera')"><span>▣</span> 摄影机<small>{{doc.camera.keys.length}} 帧</small></button><div v-for="o in doc.objects" :key="o.id" class="object-row" :class="{active:selected===o.id,hidden:!o.visible}"><button class="object-name" @click="select(o.id)" @contextmenu.prevent="select(o.id);menu={x:$event.clientX,y:$event.clientY}"><i :style="{background:o.color}"/>{{o.name}}</button><button :aria-label="`${o.visible ? '隐藏' : '显示'}${o.name}`" @click="patchObject(o.id,{visible:!o.visible})">{{o.visible ? '◉' : '○'}}</button><button :aria-label="`${o.locked ? '解锁' : '锁定'}${o.name}`" @click="patchObject(o.id,{locked:!o.locked})">{{o.locked ? '▣' : '▫'}}</button></div></div><div class="scene-bottom"><button :disabled="!!doc.objects.length" title="空场景可载入可编辑的走位练习" @click="preset()">载入双人走位示例</button><button :disabled="!!doc.objects.length" title="空场景可载入 12 秒连续动作练习" @click="preset(true)">载入双人动作练习</button><button :disabled="!!doc.objects.length" title="空场景可载入城池、官军、土匪和大炮的动作练习" @click="battlePreset">载入炮轰城门示例</button><button :disabled="!doc.objects.length" @click="clear">清空场景</button><p>走位排空间，动作编排节奏，关节微调表演。点击「操作参考」查看完整练习。</p></div></aside>
      <main class="viewport-wrap" @contextmenu.prevent="menu={x:$event.clientX,y:$event.clientY}"><DirectorViewport ref="viewport" :document="doc" :frame="frame" :selected="selected" :tool="tool" :joint="performanceEditor.joint.value" :playing="playing" :guides="guides" @select="select" @joint="performanceEditor.joint.value=$event" @joint-rotation="performanceEditor.rotateJoint" @seek="seek" @transform="transform" @error="message=$event"/><div class="transform-tools"><button v-for="(label,mode) in {translate:'移动',rotate:'旋转',scale:'缩放',pose:'姿态'}" :key="mode" :class="{active:tool===mode}" @click="tool=mode">{{label}}</button><i/><button :class="{active:guides}" @click="guides=!guides">辅助线</button><i/><button :disabled="!store.canUndo.value" aria-label="撤销导演修改" @click="history('undo')">↶</button><button :disabled="!store.canRedo.value" aria-label="重做导演修改" @click="history('redo')">↷</button></div></main>
      <DirectorInspector :document="doc" :selected="selected" :frame="frame" :joint="performanceEditor.joint.value" :selected-clip="performanceEditor.selectedClip.value" :can-paste="performanceEditor.canPaste.value" :pose-mode="tool==='pose'" :clip-selection="performanceEditor.clipSelection.value" @object="patchObject(selected,$event)" @object-key="patchKey" @camera-key="patchCamera" @add-key="key" @delete-key="deleteKey" @duplicate="duplicate" @remove="remove" @seek="seek" @joint="performanceEditor.joint.value=$event;tool='pose'" @pose="patchKey({pose:$event})" @copy-pose="performanceEditor.copyPose" @paste-pose="performanceEditor.pastePose" @mirror-pose="performanceEditor.mirrorPose" @add-clip="performanceEditor.addClip" @select-clip="performanceEditor.selectClip" @patch-clip="performanceEditor.patchClip" @remove-clip="performanceEditor.removeClip" @duplicate-clip="performanceEditor.duplicateClip" @retime="performanceEditor.retime" @follow="performanceEditor.follow" @patch-follow="performanceEditor.patchFollow"/>
      <DirectorTimeline :selected-clip="performanceEditor.selectedClip.value" :document="doc" :frame="frame" :selected="selected" :playing="playing" @seek="seek" @play="play" @select="select" @add-key="key" @clip="(id,clip)=>{select(id);performanceEditor.selectClip(clip)}" @move-key="(id,from,to,copy)=>{select(id);seek(from);performanceEditor.retime(to,copy)}"/>
    </div>
    <div v-else class="loading-studio">{{store.error.value ? '工程读取失败，可重试或返回画布' : '正在读取导演工程…'}}</div>
    <div v-if="menu" class="director-menu" role="menu" :style="menuPosition" @pointerdown.stop><span>场景操作</span><button v-for="(label,kind) in directorKinds" :key="kind" role="menuitem" @click="add(kind)">＋ {{label}}</button><hr><button role="menuitem" :disabled="!object" @click="duplicate">复制选中对象</button><button role="menuitem" :disabled="!object || object.locked" @click="remove">删除选中对象</button><button role="menuitem" @click="viewport?.focus('top');menu=undefined">俯视布局</button></div>
    <DirectorGuide v-if="guideOpen" :empty="!doc.objects.length" @close="guideOpen=false" @example="preset(true)"/>
    <DirectorCaptureDialog v-if="captureOpen" @close="captureOpen=false" @import="importDocument"/><DirectorImportDialog v-if="importOpen" @close="importOpen=false" @import="importDocument"/>
    <div v-if="videoUrl" class="video-review" role="dialog" aria-label="导出的白模视频预览"><header><span>白模预演已导出 · 可回放检查动作与运镜</span><a :href="videoUrl" :download="`${filename()}-白模预演.mp4`">下载 MP4</a><button :disabled="referenceBusy||!!videoReference||referenceUnknown" @click="saveVideoReference">{{referenceBusy?'正在保存…':videoReference?'动作参考已保存':'保存为本项目动作参考'}}</button><button :disabled="referenceBusy" aria-label="关闭白模视频回放" @click="closeVideo">×</button></header><p v-if="videoReference" class="reference-saved">{{videoReference.name}} · {{videoReference.duration.toFixed(2)}} 秒 · 在分镜中刷新参考列表后选用。上传只保存素材。</p><video :src="videoUrl" controls playsinline/></div>
  </div>
</template>
